<template><footer class="table-pager"><div class="pager-meta">共 {{ total }} 项 · 第 {{ page }} / {{ pages }} 页</div><div class="pager-controls"><label class="page-size-label">每页<select class="page-size-select" :value="size" @change="$emit('size',Number($event.target.value))"><option v-for="n in [20,50,100]" :key="n" :value="n">{{n}}</option></select></label><button class="pager-btn" data-action="pagePrev" :disabled="page<=1 || busy" @click="$emit('page',page-1)">上一页</button><span class="page-number-group"><button v-for="n in numbers" :key="n" class="pager-btn" :class="{current:n===page}" :disabled="busy" @click="$emit('page',n)">{{n}}</button></span><button class="pager-btn" data-action="pageNext" :disabled="page>=pages || busy" @click="$emit('page',page+1)">下一页</button></div></footer></template>
<script setup>import { computed } from 'vue';const props=defineProps({page:{default:1},total:{default:0},size:{default:50},busy:Boolean});defineEmits(['page','size']);const pages=computed(()=>Math.max(1,Math.ceil(props.total/props.size)));const numbers=computed(()=>Array.from({length:Math.min(5,pages.value)},(_,i)=>Math.min(Math.max(1,props.page-2),Math.max(1,pages.value-4))+i));</script>
